function mirrorReflection(p, q) {
  let a = p;
  let b = q;
  while (b !== 0) {
    const rest = a % b;
    a = b;
    b = rest;
  }
  const lcm = (p / a) * q;
  const roomsAcross = lcm / q;
  const roomsUp = lcm / p;
  if (roomsAcross % 2 === 0) {
    return 2;
  }
  if (roomsUp % 2 === 0) {
    return 0;
  }
  return 1;
}

