function mirrorReflection(p, q) {
  // Bounce the beam wall to wall: each crossing of the room moves it q up or down.
  let onEast = false;
  let height = 0;
  let goingUp = true;
  for (;;) {
    onEast = !onEast;
    height += goingUp ? q : -q;
    if (height > p) {
      height = 2 * p - height;
      goingUp = false;
    } else if (height < 0) {
      height = -height;
      goingUp = true;
    }
    if (height === p) return onEast ? 1 : 2;
    if (height === 0 && onEast) return 0;
  }
}

