function generate(rand, size) {
  const maxP = size === 'large' ? 1000 : 24;
  const p = size === 'large' ? 500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * maxP);
  if (rand() < 0.3) {
    // Share a power of two between p and q so the reduction step matters.
    const factor = 2 ** (1 + Math.floor(rand() * 3));
    const base = Math.max(1, Math.floor(p / factor));
    const q = 1 + Math.floor(rand() * base);
    return [base * factor, q * factor];
  }
  return [p, 1 + Math.floor(rand() * p)];
}
